import{_ as c,C as i,o as s,c as d,b as n,w as t,Z as l,k as a,a as e,Q as p,H as r}from"./chunks/framework.861fad59.js";const f=JSON.parse('{"title":"01 · ChatGPT 到底是如何回答问题的？","description":"","frontmatter":{"title":"01 · ChatGPT 到底是如何回答问题的？"},"headers":[],"relativePath":"guide/ai/chatbot-course/01-how-chatgpt-works.md","filePath":"guide/ai/chatbot-course/01-how-chatgpt-works.md","lastUpdated":1792048633000}'),E={name:"guide/ai/chatbot-course/01-how-chatgpt-works.md"},h=a("h1",{id:"第-01-篇-chatgpt-到底是如何回答问题的",tabindex:"-1"},[e("第 01 篇：ChatGPT 到底是如何回答问题的？ "),a("a",{class:"header-anchor",href:"#第-01-篇-chatgpt-到底是如何回答问题的","aria-label":'Permalink to "第 01 篇：ChatGPT 到底是如何回答问题的？"'},"​")],-1),u=a("blockquote",null,[a("p",null,"第一阶段：AI 与大模型基础｜阅读约 8 分钟")],-1),A=a("h2",{id:"_1-从用户输入到模型回答",tabindex:"-1"},[e("1. 从用户输入到模型回答 "),a("a",{class:"header-anchor",href:"#_1-从用户输入到模型回答","aria-label":'Permalink to "1. 从用户输入到模型回答"'},"​")],-1),_=a("p",null,"用户问「为什么 JavaScript 是单线程的？」基础语言模型不是直接查询固定答案，而是根据上下文逐步预测下一个 Token。",-1),y=p(`<p>这种逐个生成的机制叫<strong>自回归生成</strong>。现代聊天产品还可能组合搜索、工具、记忆和安全策略，因此产品不等于基础模型。</p><h2 id="_2-token-是什么" tabindex="-1">2. Token 是什么？ <a class="header-anchor" href="#_2-token-是什么" aria-label="Permalink to &quot;2. Token 是什么？&quot;">​</a></h2><p>Token 是模型处理文本的基本单位，不一定等于汉字或英文单词。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">输入：我是一名前端开发工程师</span></span>
<span class="line"><span style="color:#e1e4e8;">示意分词：[&quot;我&quot;,&quot;是一名&quot;,&quot;前端&quot;,&quot;开发&quot;,&quot;工程师&quot;]</span></span>
<span class="line"><span style="color:#e1e4e8;">示意 ID：[123,456,789,234,567]</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">输入：我是一名前端开发工程师</span></span>
<span class="line"><span style="color:#24292e;">示意分词：[&quot;我&quot;,&quot;是一名&quot;,&quot;前端&quot;,&quot;开发&quot;,&quot;工程师&quot;]</span></span>
<span class="line"><span style="color:#24292e;">示意 ID：[123,456,789,234,567]</span></span></code></pre></div><p>以上仅为教学示例，真实切分由 Tokenizer 决定。Token ID 是编号，不直接代表语义。</p><h2 id="_3-为什么能逐字生成" tabindex="-1">3. 为什么能逐字生成？ <a class="header-anchor" href="#_3-为什么能逐字生成" aria-label="Permalink to &quot;3. 为什么能逐字生成？&quot;">​</a></h2><p>给定「JavaScript 是一种」，模型可能为后续 Token 计算以下<strong>假设</strong>概率：</p><table><thead><tr><th>候选</th><th style="text-align:right;">概率</th></tr></thead><tbody><tr><td>编程</td><td style="text-align:right;">65%</td></tr><tr><td>脚本</td><td style="text-align:right;">20%</td></tr><tr><td>动态</td><td style="text-align:right;">10%</td></tr><tr><td>其他</td><td style="text-align:right;">5%</td></tr></tbody></table><p>选出「编程」后，模型再基于「JavaScript 是一种编程」预测后续 Token，直到结束。选择策略可能受 Temperature、Top-p 等参数影响，不一定每次都选最高概率。</p><h2 id="_4-transformer-与-attention" tabindex="-1">4. Transformer 与 Attention <a class="header-anchor" href="#_4-transformer-与-attention" aria-label="Permalink to &quot;4. Transformer 与 Attention&quot;">​</a></h2><p>Transformer 是现代大语言模型广泛采用的架构。Attention 帮助模型在处理某个位置时利用上下文信息。</p><p>例如「小明把电脑放在桌子上，因为它太重了」中的「它」，需要参考其他词语来判断指代。Attention 是可学习的数值机制，不是硬编码的规则，也不能单独作为模型决策的完整解释。</p><h2 id="_5-为什么模型会编程" tabindex="-1">5. 为什么模型会编程？ <a class="header-anchor" href="#_5-为什么模型会编程" aria-label="Permalink to &quot;5. 为什么模型会编程？&quot;">​</a></h2><p>训练过程中模型学习了大量语言、代码结构和统计规律，因此可以生成：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#F97583;">const</span><span style="color:#E1E4E8;"> </span><span style="color:#B392F0;">sum</span><span style="color:#E1E4E8;"> </span><span style="color:#F97583;">=</span><span style="color:#E1E4E8;"> (</span><span style="color:#FFAB70;">a</span><span style="color:#F97583;">:</span><span style="color:#E1E4E8;"> </span><span style="color:#79B8FF;">number</span><span style="color:#E1E4E8;">, </span><span style="color:#FFAB70;">b</span><span style="color:#F97583;">:</span><span style="color:#E1E4E8;"> </span><span style="color:#79B8FF;">number</span><span style="color:#E1E4E8;">) </span><span style="color:#F97583;">=&gt;</span><span style="color:#E1E4E8;"> a </span><span style="color:#F97583;">+</span><span style="color:#E1E4E8;"> b;</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#D73A49;">const</span><span style="color:#24292E;"> </span><span style="color:#6F42C1;">sum</span><span style="color:#24292E;"> </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> (</span><span style="color:#E36209;">a</span><span style="color:#D73A49;">:</span><span style="color:#24292E;"> </span><span style="color:#005CC5;">number</span><span style="color:#24292E;">, </span><span style="color:#E36209;">b</span><span style="color:#D73A49;">:</span><span style="color:#24292E;"> </span><span style="color:#005CC5;">number</span><span style="color:#24292E;">) </span><span style="color:#D73A49;">=&gt;</span><span style="color:#24292E;"> a </span><span style="color:#D73A49;">+</span><span style="color:#24292E;"> b;</span></span></code></pre></div><p>但<strong>生成合理代码不代表代码一定正确</strong>。工程上仍需要类型检查、测试和审查。</p><h2 id="_6-从-react-node-js-看聊天系统" tabindex="-1">6. 从 React + Node.js 看聊天系统 <a class="header-anchor" href="#_6-从-react-node-js-看聊天系统" aria-label="Permalink to &quot;6. 从 React + Node.js 看聊天系统&quot;">​</a></h2>`,17),B=p('<p>LLM 负责内容生成，聊天应用还需要会话管理、鉴权、存储、流式输出、限流和安全机制。</p><h2 id="_7-复习要点" tabindex="-1">7. 复习要点 <a class="header-anchor" href="#_7-复习要点" aria-label="Permalink to &quot;7. 复习要点&quot;">​</a></h2><ul><li>LLM：学习语言规律并生成 Token 的模型。</li><li>Token：文本的基本处理单位。</li><li>Tokenizer：将文本转换为 Token ID。</li><li>Transformer：利用上下文处理序列的架构。</li><li>Attention：按权重聚合不同位置的信息。</li></ul><h2 id="学习疑问与解答" tabindex="-1">学习疑问与解答 <a class="header-anchor" href="#学习疑问与解答" aria-label="Permalink to &quot;学习疑问与解答&quot;">​</a></h2><p>目前暂无针对本篇的新问题，后续在此追加。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>为什么模型可能给出语气自信但事实错误的回答？提示：预测下一个 Token 与验证事实真实性不是同一回事。</p><p><a href="./02-token-and-embedding">下一篇：Token 与 Embedding →</a></p>',8);function b(g,k,m,T,D,q){const o=i("Mermaid");return s(),d("div",null,[h,u,A,_,(s(),n(l,null,{default:t(()=>[r(o,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20TD%0A%20A%5B%E7%94%A8%E6%88%B7%E8%BE%93%E5%85%A5%5D%20--%3E%20B%5BTokenizer%5D%0A%20B%20--%3E%20C%5BToken%20ID%20%E4%B8%8E%20Embedding%5D%0A%20C%20--%3E%20D%5BTransformer%20%E8%AE%A1%E7%AE%97%5D%0A%20D%20--%3E%20E%5B%E4%B8%8B%E4%B8%80%E4%B8%AA%20Token%20%E6%A6%82%E7%8E%87%5D%0A%20E%20--%3E%20F%5B%E9%80%89%E6%8B%A9%20Token%5D%0A%20F%20--%3E%20G%7B%E6%98%AF%E5%90%A6%E7%BB%93%E6%9D%9F%7D%0A%20G%20--%20%E5%90%A6%20--%3E%20D%0A%20G%20--%20%E6%98%AF%20--%3E%20H%5B%E8%BE%93%E5%87%BA%E5%9B%9E%E7%AD%94%5D%0A"})]),fallback:t(()=>[e(" Loading... ")]),_:1})),y,(s(),n(l,null,{default:t(()=>[r(o,{id:"mermaid-105",class:"mermaid",graph:"flowchart%20TD%0A%20A%5BReact%20%E8%81%8A%E5%A4%A9%20UI%5D%20--%3E%7CHTTP%7C%20B%5BNode.js%20API%5D%0A%20B%20--%3E%20C%5B%E9%89%B4%E6%9D%83%E4%B8%8E%20Messages%20%E7%BB%84%E8%A3%85%5D%0A%20C%20--%3E%20D%5BLLM%20API%5D%0A%20D%20--%3E%7C%E6%B5%81%E5%BC%8F%E7%BB%93%E6%9E%9C%7C%20B%0A%20B%20--%3E%7CSSE%7C%20A%0A%20B%20%3C--%3E%20E%5B(%E8%81%8A%E5%A4%A9%E8%AE%B0%E5%BD%95%E6%95%B0%E6%8D%AE%E5%BA%93)%5D%0A"})]),fallback:t(()=>[e(" Loading... ")]),_:1})),B])}const P=c(E,[["render",b]]);export{f as __pageData,P as default};
